(7150462, 1096597, 30982, '<td valign="top">Almost looks as though you took a tree and put it on a giant scanner.  Cool effect.</td>', 'Almost looks as though you took a tree and put it on a giant scanner.  Cool effect.', '2014-01-01 20:51:43.000000', NULL, 1),
(7150463, 1096525, 30982, '<td valign="top">This thing looks like it comes to life and eats anything left beneath it when no one is looking.  Those trash cans are gonna be history.</td>', 'This thing looks like it comes to life and eats anything left beneath it when no one is looking.  Those trash cans are gonna be history.', '2014-01-01 20:52:12.000000', NULL, 1),
