(7150465, 1096100, 161988, '<td valign="top">The frequently done single tree shot. It''s so hard to make it extraordinary but I believe you have. (8)</td>', 'The frequently done single tree shot. It''s so hard to make it extraordinary but I believe you have. (8)', '2014-01-01 20:52:32.000000', NULL, 1),
(7150466, 1096596, 30982, '<td valign="top">This makes me smile.  Wonderful warmth radiating from the trunk of that tree.  Great balance to the shot, too.</td>', 'This makes me smile.  Wonderful warmth radiating from the trunk of that tree.  Great balance to the shot, too.', '2014-01-01 20:52:53.000000', NULL, 1),
