(7150468, 1096170, 30982, '<td valign="top">Nice peaceful image.</td>', 'Nice peaceful image.', '2014-01-01 20:53:04.000000', NULL, 1),
(7150469, 1096565, 161988, '<td valign="top">Love the colors,the sky and the reflection in the water.</td>', 'Love the colors,the sky and the reflection in the water.', '2014-01-01 20:53:52.000000', NULL, 1),
(7150470, 1096155, 161988, '<td valign="top">Beautiful colors.</td>', 'Beautiful colors.', '2014-01-01 20:54:53.000000', NULL, 1),
