(7150479, 1096491, 30982, '<td valign="top">That''s a LOT of lights!!  I''m guessing they stay on the tree all year?</td>', 'That''s a LOT of lights!!  I''m guessing they stay on the tree all year?', '2014-01-01 21:01:31.000000', NULL, 1),
(7150480, 1096591, 30982, '<td valign="top">From the warmth of the car, I''m guessing.  Nice snowscape!</td>', 'From the warmth of the car, I''m guessing.  Nice snowscape!', '2014-01-01 21:01:50.000000', NULL, 1),
(7150481, 1096576, 30982, '<td valign="top">The slender tree on the left seems a bit in awe of the more solid one center.  And love the sunstar.</td>', 'The slender tree on the left seems a bit in awe of the more solid one center.  And love the sunstar.', '2014-01-01 21:02:20.000000', NULL, 1),
