(7150485, 1096519, 30982, '<td valign="top">Excellent use of negative space, and I love how it just starts to fade to blue at the top.</td>', 'Excellent use of negative space, and I love how it just starts to fade to blue at the top.', '2014-01-01 21:03:23.000000', NULL, 1),
(7150486, 1096283, 30982, '<td valign="top">Very nice use of the curve of the land - makes for a nicely balanced composition and pleasing lines.</td>', 'Very nice use of the curve of the land - makes for a nicely balanced composition and pleasing lines.', '2014-01-01 21:03:47.000000', NULL, 1),
